from collections import deque
class Solution:
    def maxWeight(self, n: int, edges: List[List[int]], k: int, t: int) -> int:
        if k == 0:
            return 0
        adj = [[] for _ in range(n)]; indeg = [0]*n
        for u, v, w in edges:
            adj[u].append((v, w)); indeg[v] += 1
        dq = deque(i for i in range(n) if indeg[i] == 0)
        order = []
        while dq:
            u = dq.popleft(); order.append(u)
            for v, _ in adj[u]:
                indeg[v] -= 1
                if indeg[v] == 0: dq.append(v)
        NEG = float('-inf')
        dp = [[NEG]*(k+1) for _ in range(n)]
        for u in order: dp[u][0] = 0
        ans = -1
        for u in order:
            for v, w in adj[u]:
                for j in range(k):
                    s = dp[u][j] + w
                    if dp[u][j] > NEG and s < t and s > dp[v][j+1]:
                        dp[v][j+1] = s
                        if j+1 == k: ans = max(ans, s)
        return ans

