class Solution {
public:
    int maxWeight(int n, vector<vector<int>>& edges, int k, int t) {
        if (k == 0) return 0;
        vector<vector<pair<int,int>>> adj(n); vector<int> indeg(n, 0);
        for (auto& e : edges) { adj[e[0]].push_back({e[1], e[2]}); indeg[e[1]]++; }
        queue<int> dq; for (int i = 0; i < n; i++) if (!indeg[i]) dq.push(i);
        vector<int> order;
        while (!dq.empty()) { int u = dq.front(); dq.pop(); order.push_back(u);
            for (auto& [v, w] : adj[u]) if (--indeg[v] == 0) dq.push(v); }
        const int NEG = INT_MIN / 2;
        vector<vector<int>> dp(n, vector<int>(k + 1, NEG));
        for (int u : order) dp[u][0] = 0;
        int ans = -1;
        for (int u : order)
            for (auto& [v, w] : adj[u])
                for (int j = 0; j < k; j++) {
                    if (dp[u][j] <= NEG) continue;
                    int s = dp[u][j] + w;
                    if (s < t && s > dp[v][j+1]) { dp[v][j+1] = s; if (j+1 == k) ans = max(ans, s); }
                }
        return ans;
    }
};

