class Solution {
    public int maxWeight(int n, int[][] edges, int k, int t) {
        if (k == 0) return 0;
        List<List<int[]>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        int[] indeg = new int[n];
        for (int[] e : edges) { adj.get(e[0]).add(new int[]{e[1], e[2]}); indeg[e[1]]++; }
        Deque<Integer> dq = new ArrayDeque<>();
        for (int i = 0; i < n; i++) if (indeg[i] == 0) dq.add(i);
        List<Integer> order = new ArrayList<>();
        while (!dq.isEmpty()) { int u = dq.poll(); order.add(u);
            for (int[] vw : adj.get(u)) if (--indeg[vw[0]] == 0) dq.add(vw[0]); }
        final int NEG = Integer.MIN_VALUE / 2;
        int[][] dp = new int[n][k + 1];
        for (int[] row : dp) java.util.Arrays.fill(row, NEG);
        for (int u : order) dp[u][0] = 0;
        int ans = -1;
        for (int u : order)
            for (int[] vw : adj.get(u))
                for (int j = 0; j < k; j++) {
                    if (dp[u][j] <= NEG) continue;
                    int s = dp[u][j] + vw[1];
                    if (s < t && s > dp[vw[0]][j+1]) { dp[vw[0]][j+1] = s; if (j+1 == k) ans = Math.max(ans, s); }
                }
        return ans;
    }
}

