var maxWeight = function(n, edges, k, t) {
    if (k === 0) return 0;
    const adj = Array.from({length: n}, () => []), indeg = new Array(n).fill(0);
    for (const [u, v, w] of edges) { adj[u].push([v, w]); indeg[v]++; }
    const dq = [];
    for (let i = 0; i < n; i++) if (indeg[i] === 0) dq.push(i);
    const order = [];
    for (let h = 0; h < dq.length; h++) {
        const u = dq[h]; order.push(u);
        for (const [v] of adj[u]) if (--indeg[v] === 0) dq.push(v);
    }
    const NEG = -Infinity;
    const dp = Array.from({length: n}, () => new Array(k + 1).fill(NEG));
    for (const u of order) dp[u][0] = 0;
    let ans = -1;
    for (const u of order)
        for (const [v, w] of adj[u])
            for (let j = 0; j < k; j++) {
                if (dp[u][j] === NEG) continue;
                const s = dp[u][j] + w;
                if (s < t && s > dp[v][j+1]) { dp[v][j+1] = s; if (j+1 === k) ans = Math.max(ans, s); }
            }
    return ans;
};
